From 2ed5f0384eae4180267c5625da56f4d8620ebea0 Mon Sep 17 00:00:00 2001
From: oscartu <oscarmh.tu@moxa.com>
Date: Tue, 4 Aug 2026 10:35:06 +0800
Subject: [PATCH 1/2] [Plan E Task 3] ies-auto-mibs: keep synthesised index
 columns local

A live diff against mainline showed 8691.603.3.2.2.1.1.1.{1..12} -
rstpStatPortTable column 1 - missing from the Plan E build.
net_mxRSTPdb.h declares columns 2-16 only; column 1 is synthesised at
registration time by GenerateTableIndexEntry and exists nowhere but
ies-auto-mibs, so forwarding its GET to ISS returned noSuchInstance and
dropped the column from every walk. 55 tables have this shape, 51 of
them served by ISS.

MAKEUP_INDEX_FOR_ISS could not be used to detect these: it is set
outside the column-2 guard, so every column of an affected table carries
it. A dedicated SYNTHETIC_INDEX flag is set on the cloned entry only.

Verified on the DUT: the 12 OIDs are back and GET p100 stays at 0.00s.

Known incomplete - see ledger: sysObjectID (GENERATE_SYS_OID) is still
forwarded and returns ISS's generic .1.3.6.1.2.1 instead of the Moxa
product OID. The structural fix is to move forwarding after the local
value checks rather than enumerating flags.
---
 ies-auto-mibs/ies_auto_mibs.c         | 15 ++++++++++++---
 ies-auto-mibs/moxa_snmp_handle_util.c |  6 ++++++
 snmp_tools/inc/ies_auto_mibs_handle.h |  6 ++++++
 3 files changed, 24 insertions(+), 3 deletions(-)

diff --git a/ies-auto-mibs/ies_auto_mibs.c b/ies-auto-mibs/ies_auto_mibs.c
index c716d42..f4c2f0c 100755
--- a/ies-auto-mibs/ies_auto_mibs.c
+++ b/ies-auto-mibs/ies_auto_mibs.c
@@ -3196,34 +3196,43 @@ mox_snmp_handle_entry
             if (strncmp(snmp_username, rwuser_list[token_cnt], RWUSER_NAME_SIZE) == 0) {
                 memset(security_token, 0, sizeof(security_token));
                 snprintf(security_token, sizeof(security_token), "%s", security_tokens[token_cnt+1]);
                 break;
             }
         }
     }

     if ( MODE_IS_GET(reqinfo->mode) ) 
     {
         LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s@%d: entry %s \n",
             __func__, __LINE__, entry->uri );

         /* per D2: every GET goes to a subagent - no RO/RW distinction, no list.
          * Falls through to the local slow path below when the subagent is not
-         * connected or does not cover this OID. */
-        if ( mox_snmp_forward_get_to_subagent(reginfo, reqinfo, request) == 0 )
+         * connected or does not cover this OID.
+         *
+         * Exception: index columns synthesised by
+         * moxaSnmpHandle_UtilMibEntryGenerateTableIndexEntry() exist only
+         * inside ies-auto-mibs. The table's header declares no column 1, so a
+         * subagent answers noSuchInstance and the column disappears from every
+         * walk. Those stay on the local path. */
+        if ( !IES_FLAG_BITS_CHK(IES_FLAG_SNMP_SYNTHETIC_INDEX, entry->flags) )
         {
-            return SNMP_ERR_NOERROR;
+            if ( mox_snmp_forward_get_to_subagent(reginfo, reqinfo, request) == 0 )
+            {
+                return SNMP_ERR_NOERROR;
+            }
         }

         if ( moxaSnmpHandle_ChkEntryGetValue(entry) == 0 )
         {
             if ( moxaSnmpHandle_ExeEntryGetValue(reqinfo, request, entry) == 0 )
             {
                 return SNMP_ERR_NOERROR;
             }
             return SNMP_ERR_BADVALUE;
         }

         if ( moxaSnmpHandle_UtilMibEntryCheckFromUri(entry) )
         {
             if ( IES_NOERR != entry_handle_generate_uri_value_file(entry, &fp) ) 
             {
diff --git a/ies-auto-mibs/moxa_snmp_handle_util.c b/ies-auto-mibs/moxa_snmp_handle_util.c
index e5c80e3..50d3b84 100755
--- a/ies-auto-mibs/moxa_snmp_handle_util.c
+++ b/ies-auto-mibs/moxa_snmp_handle_util.c
@@ -160,30 +160,36 @@ int32_t moxaSnmpHandle_UtilMibEntryCreateIndexEntry( struct ies_auto_mibs_entry

     entryIndex = (struct ies_auto_mibs_entry *) malloc ( sizeof(*entry) );

     if ( entryIndex == NULL )
     {
         LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
         return (-1);
     }
     memcpy(entryIndex, entry, sizeof(*entry));

     entryIndex->oid_list[entryIndex->oid_len - 1] = 1;
     entryIndex->val_type                          = SNMP_DATA_TYPE_INTEGER;
     entryIndex->mode                              = HANDLER_CAN_RONLY;

     memcpy(entryIndex->flags, entry->flags, sizeof(entry->flags));
+
+    /* Mark this as a synthesised index column. Set on the clone only - the
+     * parent is a real column that a subagent can serve. Must come after the
+     * memcpy above, which overwrites the whole flags array. */
+    IES_FLAG_BITS_SET(IES_FLAG_SNMP_SYNTHETIC_INDEX, entryIndex->flags);
+
     snprintf(entryIndex->name,      IES_MAX_URI_INDEX, "%s", "index");
     snprintf(entryIndex->uri_index, IES_MAX_URI_INDEX, "%s", "index");

     *retEntry = entryIndex;
     return 0;
 }


 /**
  * @brief register moxa snmp entry into netSNMP

  * @param[in]    entry        moxa snmp entry

  * @returns      0 means success, others fail.
  */
diff --git a/snmp_tools/inc/ies_auto_mibs_handle.h b/snmp_tools/inc/ies_auto_mibs_handle.h
index 6676e72..378d7ee 100755
--- a/snmp_tools/inc/ies_auto_mibs_handle.h
+++ b/snmp_tools/inc/ies_auto_mibs_handle.h
@@ -77,30 +77,36 @@ enum {

     IES_FLAG_SNMP_MAKEUP_INDEX,          /* special handle  : for some reason, iss won't generate table index for mib_db,
                                                               so we have to makeup index for it */
     IES_FLAG_SNMP_MAKEUP_INDEX_FOR_ISS,  /* special handle  : for some reason, iss won't generate table index for mib_db,
                                                               so we have to makeup index for it */
     IES_FLAG_SNMP_GENERATE_SYS_OID,      /* special handle  : generate system object ID */
     IES_FLAG_SNMP_CHANGE_VALUE_SCALE,    /* special handle  : for some reason, value scale different from snmp and uri_config */
     IES_FLAG_SNMP_URI_FIXED_VALUE,       /* special handle  : fixed value in snmpd */
     IES_FLAG_SNMP_MULTIPLE_INDEX_TABLE,  /* special handle  : oid index is 1 but this is multiple index table */
     IES_FLAG_SNMP_INDEX_NOT_START_FROM_1,/* special handle  : oid index Not start 1. from 0 or from portChannel-index */
     IES_FLAG_SNMP_INDEX_NOT_IN_ORDER,    /* special handle :  In some table ( like laConfigMainTable ) , the table-index
                                                               may not be in-order. So the table-index should be
                                                               genegrated from ISS like iftable, not auto-generate by
                                                               SNMP-Framework.
                                           */
+    IES_FLAG_SNMP_SYNTHETIC_INDEX,       /* special handle  : index column synthesised by
+                                                              GenerateTableIndexEntry(). It exists
+                                                              only inside ies-auto-mibs - the table's
+                                                              header declares no column 1 - so no
+                                                              subagent can serve it and its GET must
+                                                              stay on the local path. */
     IES_FLAG_SNMP_MAX,
 };


 #define AUTO_MIB_CMD_URI_CTRL_CLIENT  "/sbin/ies_uri_handle_client "

 #define AUTO_MIB_PATH                 "/moxa/run/auto_mibs"
 #define SNMPD_CONFIG_FILE             "/moxa/run/snmp/snmpd.conf"

 #define AUTO_MIB_MAX_DEV_PORT         (64)
 #define AUTO_MIB_MAX_DAYS_OF_WEEK     (8)  // for alignment !!
 #define AUTO_MIB_MAX_SET_DELAY        (1)
 #define AUTO_MIB_MAX_ENTRY_ARRAY      (128)


-- 
